maze = [list(line) for line in open("maze.txt").read().splitlines()]
R, C = 27, 27

# Check all possible passage locations:
# Horizontal passage: (2*i+1, 2*j) where cells are (2*i+1, 2*j-1) and (2*i+1, 2*j+1)
# Vertical passage: (2*i, 2*j+1) where cells are (2*i-1, 2*j+1) and (2*i+1, 2*j+1)

# A spanning tree on 13x13 graph has 169 vertices and 168 edges.
# Currently total open = 336 = 169 cells + 167 edges!
# Exactly ONE edge was removed (or is a wall) splitting the spanning tree into 2 components!
# That means there is EXACTLY ONE passage wall that connects component 0 and component 1 at cell-passage positions!

visited = set()
components = []
for r in range(R):
    for c in range(C):
        if maze[r][c] != "#" and (r, c) not in visited:
            comp = set()
            q = [(r, c)]
            visited.add((r, c))
            for cr, cc in q:
                comp.add((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < R and 0 <= nc < C and maze[nr][nc] != "#" and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)

c0, c1 = components[0], components[1]

# Check candidate passages:
candidates = []
# Horizontal:
for i in range(13):
    r = 2*i + 1
    for j in range(1, 13):
        c = 2*j
        # neighbors are (r, c-1) and (r, c+1)
        if (r, c-1) in c0 and (r, c+1) in c1:
            candidates.append((r, c, "horizontal", (r, c-1), (r, c+1)))
        elif (r, c-1) in c1 and (r, c+1) in c0:
            candidates.append((r, c, "horizontal", (r, c+1), (r, c-1)))

# Vertical:
for i in range(1, 13):
    r = 2*i
    for j in range(13):
        c = 2*j + 1
        # neighbors are (r-1, c) and (r+1, c)
        if (r-1, c) in c0 and (r+1, c) in c1:
            candidates.append((r, c, "vertical", (r-1, c), (r+1, c)))
        elif (r-1, c) in c1 and (r+1, c) in c0:
            candidates.append((r, c, "vertical", (r+1, c), (r-1, c)))

print("Candidate passages that reconnect the tree:")
