from collections import deque
import glob

def solve(filename):
    maze = open(filename).read().splitlines()
    start = None
    end = None
    for r, row in enumerate(maze):
        for c, ch in enumerate(row):
            if ch == "@": start = (r, c)
            elif ch == "E": end = (r, c)
    q = deque([start])
    visited = {start}
    while q:
        r, c = q.popleft()
        if (r, c) == end: return True
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] != "#":
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
    return False

for p in sorted(glob.glob("../ep*/maze.txt")):
    print(p, solve(p))
'"}

