parent_s = {start: None}
q = deque([start])
while q:
    curr = q.popleft()
    for dr, dc in dirs.values():
        nr, nc = curr[0] + dr, curr[1] + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            if grid[nr][nc] != "#" and (nr, nc) not in dist_s:
                dist_s[(nr, nc)] = dist_s[curr] + 1
                parent_s[(nr, nc)] = curr
                q.append((nr, nc))

# BFS from end
dist_e = {end: 0}
parent_e = {end: None}
q = deque([end])
while q:
    curr = q.popleft()
    for dr, dc in dirs.values():
        nr, nc = curr[0] + dr, curr[1] + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            if grid[nr][nc] != "#" and (nr, nc) not in dist_e:
                dist_e[(nr, nc)] = dist_e[curr] + 1
                parent_e[(nr, nc)] = curr
                q.append((nr, nc))

# Look at candidates where (block[0]%2) + (block[1]%2) == 1
# that connect dist_s and dist_e
blocks = []
for r in range(len(grid)):
    for c in range(len(grid[r])):
        if (r % 2) + (c % 2) == 1 and grid[r][c] == "#":
            adj_s = [n for n in [(r+1,c), (r-1,c), (r,c+1), (r,c-1)] if n in dist_s]
            adj_e = [n for n in [(r+1,c), (r-1,c), (r,c+1), (r,c-1)] if n in dist_e]
            if adj_s and adj_e:
                blocks.append((r, c, adj_s, adj_e))

print("Sealed block candidates:")
