from collections import deque

def analyze(fname):
    maze = open(fname).read().splitlines()
    rows, cols = len(maze), len(maze[0])
    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if maze[r][c] == "@": start = (r, c)
            if maze[r][c] == "E": end = (r, c)

    def bfs(s):
        vis = {s}
        q = deque([s])
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and maze[nr][nc] != "#" and (nr, nc) not in vis:
                    vis.add((nr, nc))
                    q.append((nr, nc))
        return vis

    s_vis = bfs(start)
    e_vis = bfs(end)
    total_floor = sum(row.count(".") for row in maze) + 2
    print(f"{fname}: rows={rows}, cols={cols}, start={start}, end={end}")
    print(f"  reach start={len(s_vis)}, reach end={len(e_vis)}, total_floor={total_floor}")
    # find all cells that are not reachable from start or end
    other = []
    for r in range(rows):
        for c in range(cols):
            if maze[r][c] != "#" and (r, c) not in s_vis and (r, c) not in e_vis:
                other.append((r, c))
    print(f"  other floor cells: {len(other)}")

for i in range(5):
    analyze(f"../ep{i}/maze.txt")
'"}

