from collections import deque

with open("maze.txt") as f:
    grid = [list(line.rstrip("\r\n")) for line in f]

start = (1, 1)
end = (27, 27)

def reach(s):
    q = deque([s])
    vis = {s}
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0<=nr<len(grid) and 0<=nc<len(grid[nr]) and grid[nr][nc] != "#" and (nr, nc) not in vis:
                vis.add((nr, nc))
                q.append((nr, nc))
    return vis

rs = reach(start)
re = reach(end)

# A blocked corridor must be between two odd-coordinate cells:
# i.e., block has (r%2 + c%2 == 1), and its neighbors along the corridor are both odd cells (cell 1 and cell 2),
# one in rs, one in re!
corridor_blocks = []
for r in range(1, len(grid)-1):
    for c in range(1, len(grid[0])-1):
        if grid[r][c] == "#" and (r % 2 + c % 2 == 1):
            # check neighbors
            if r % 2 == 1: # horizontal corridor: (r, c-1) and (r, c+1) are odd cells
                n1, n2 = (r, c-1), (r, c+1)
            else: # vertical corridor: (r-1, c) and (r+1, c) are odd cells
                n1, n2 = (r-1, c), (r+1, c)
            if (n1 in rs and n2 in re) or (n1 in re and n2 in rs):
                corridor_blocks.append(((r, c), n1, n2))

print("Corridor blocks:", corridor_blocks)
