def reachable(maze: dict) -> set:
    """Every square a legal sequence of moves can put '@' on (the exit is not among them)."""
    grid = maze["grid"]
    seen = {maze["start"]}
    q = deque([maze["start"]])
    while q:
        p = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            n = (p[0] + dr, p[1] + dc)
            if grid[n[0]][n[1]] != WALL and n not in seen:
                seen.add(n)
                q.append(n)
    return seen


